"""Catalog of 70 BPS RI & BPS Aceh statistical table sources targeting Aceh inflation, consumption & labor."""

from dataclasses import dataclass


@dataclass(frozen=True)
class BpsTableSourceSpec:
    """Declarative metadata and endpoint URL for one BPS statistical table."""

    index: int
    dataset_slug: str
    title: str
    institution: str
    url: str
    category: str
    collection: str = "raw_bps_makro"
    aceh_specific_rows: bool = False

    @property
    def table_type(self) -> int:
        if "/statistics-table/1/" in self.url:
            return 1
        if "/statistics-table/3/" in self.url:
            return 3
        return 2


